const canvas=document.getElementById('scene'),ctx=canvas.getContext('2d');
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let W=0,H=0,dpr=1,screen='title',last=0,toastTimer;
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
function rng(n){let x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x)}
function poly(points,fill,stroke,lw=1){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.stroke()}}
function line(x1,y1,x2,y2,c,w=1){ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.strokeStyle=c;ctx.lineWidth=w;ctx.stroke()}
function drawTitle(){let g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#e69a5e');g.addColorStop(.55,'#e5b675');g.addColorStop(1,'#586b51');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);let hz=H*.49;ctx.fillStyle='#779072';ctx.fillRect(0,hz,W,H-hz);ctx.fillStyle='#4b684d';for(let i=0;i<20;i++){let x=i*W/15-30,h=60+rng(i)*95;ctx.fillRect(x,hz-h,W/22,h)}ctx.fillStyle='#d5cc9d';ctx.beginPath();ctx.arc(W*.76,H*.22,48,0,7);ctx.fill();poly([[W*.38,hz],[W*.62,hz],[W*.91,H],[W*.1,H]],'#796d54');poly([[W*.46,hz],[W*.54,hz],[W*.7,H],[W*.3,H]],'#a59878');for(let i=0;i<7;i++){let yy=hz+(H-hz)*(i/7);line(W*.5-(yy-hz)*.34,yy,W*.5+(yy-hz)*.34,yy,'#dfd2ad',Math.max(1,(yy-hz)*.014))}drawCar(W*.5,H*.77,Math.min(W*.25,210),false);for(let i=0;i<50;i++){let x=rng(i+30)*W,y=hz+rng(i+90)*(H-hz);ctx.fillStyle=i%2?'#c3c981':'#e5d7a1';ctx.fillRect(x,y,2,2)}}
function drawCar(x,y,w,damaged=false){ctx.save();ctx.translate(x,y);ctx.scale(w/180,w/180);ctx.fillStyle='#18221d77';ctx.beginPath();ctx.ellipse(0,18,102,39,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#252a24';ctx.fillRect(-88,-28,28,67);ctx.fillRect(60,-28,28,67);ctx.fillStyle=damaged?'#6d6c55':'#bc7444';ctx.beginPath();ctx.moveTo(-88,-42);ctx.quadraticCurveTo(-75,-61,-48,-62);ctx.lineTo(50,-62);ctx.quadraticCurveTo(80,-58,88,-35);ctx.lineTo(93,39);ctx.quadraticCurveTo(79,60,55,61);ctx.lineTo(-53,61);ctx.quadraticCurveTo(-84,56,-91,38);ctx.closePath();ctx.fill();ctx.strokeStyle='#29352b';ctx.lineWidth=5;ctx.stroke();ctx.fillStyle='#344940';ctx.beginPath();ctx.moveTo(-51,-53);ctx.lineTo(49,-53);ctx.lineTo(63,-18);ctx.lineTo(-61,-18);ctx.closePath();ctx.fill();ctx.fillRect(-66,20,131,28);ctx.fillStyle='#e2d7ac';ctx.fillRect(-85,-33,17,14);ctx.fillRect(68,-33,17,14);ctx.fillStyle='#322e27';ctx.fillRect(-74,-57,18,10);ctx.fillRect(55,-57,18,10);ctx.strokeStyle='#7d4d32';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-62,0);ctx.lineTo(64,0);ctx.stroke();if(damaged){ctx.fillStyle='#262c27';ctx.fillRect(-49,-7,98,19);ctx.strokeStyle='#929078';ctx.lineWidth=2;ctx.strokeRect(-49,-7,98,19)}ctx.restore()}
function drawGarage(){let sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#68796c');sky.addColorStop(.7,'#a69b76');sky.addColorStop(1,'#5c5544');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);let floor=H*.5;ctx.fillStyle='#d0b779';ctx.fillRect(0,floor,W,H-floor);ctx.strokeStyle='#897a57';ctx.lineWidth=2;for(let i=0;i<8;i++){let y=floor+i*i*3;line(0,y,W,y,'#8e805e66',1)}for(let x=0;x<W;x+=100)line(x,floor,x+(x-W/2)*.3,H,'#8e805e55',1);ctx.fillStyle='#323b30';ctx.fillRect(0,0,W,floor*.54);ctx.fillStyle='#64745e';ctx.fillRect(0,floor*.54,W,floor*.46);for(let x=0;x<W;x+=85){ctx.fillStyle=x%2?'#baa16b':'#c7ae79';ctx.fillRect(x,0,3,floor*.54)}ctx.fillStyle='#e0c58f';ctx.fillRect(W*.1,H*.05,W*.25,H*.34);ctx.fillStyle='#50665b';ctx.fillRect(W*.12,H*.075,W*.21,H*.3);line(W*.225,H*.075,W*.225,H*.375,'#d9c99e',4);line(W*.12,H*.22,W*.33,H*.22,'#d9c99e',4);ctx.fillStyle='#e7d5a5';ctx.fillRect(W*.7,H*.07,100,40);ctx.fillStyle='#71573d';ctx.font='bold 18px Oswald';ctx.fillText('TYÖKALUT',W*.7+12,H*.07+27);for(let i=0;i<5;i++){ctx.fillStyle=['#b84731','#51755c','#dfbf74','#746a51','#ae7950'][i];ctx.fillRect(W*.72+i*16,H*.2+(i%2)*18,9,47)}ctx.fillStyle='#495242';ctx.fillRect(W*.43,H*.1,W*.17,H*.19);ctx.fillStyle='#d2bd8c';ctx.fillRect(W*.435,H*.105,W*.16,H*.18);ctx.fillStyle='#596757';ctx.fillRect(W*.44,H*.11,W*.15,H*.16);drawCar(W*.5,H*.57,Math.min(W*.56,480),garage.done.battery&&garage.done.radiator&&garage.done.plugs&&garage.done.wheel);ctx.fillStyle='#2c352d';ctx.fillRect(W*.08,H*.61,70,95);ctx.fillStyle='#a56f48';ctx.fillRect(W*.095,H*.63,54,30);ctx.fillStyle='#e7d5a5';ctx.font='11px DM Mono';ctx.fillText('OIL',W*.12,H*.68);ctx.fillStyle='#ece1c7';ctx.fillRect(W*.08,H*.79,70,5);ctx.fillStyle='#30372d';ctx.fillRect(W*.81,H*.63,90,110);ctx.fillStyle='#cfb982';ctx.fillRect(W*.82,H*.65,70,10)}

const game={distance:0,speed:0,condition:100,lane:0,steer:0,obstacles:[],lastObstacle:180,elapsed:0,paused:false,done:false,collideFlash:0};
function roadCenter(p){return W*.5+Math.sin(p*.0015)*W*.11+Math.sin(p*.00057+1.4)*W*.07}
function drawDrive(dt){let horizon=H*.37;let sky=ctx.createLinearGradient(0,0,0,horizon);sky.addColorStop(0,'#83b1b2');sky.addColorStop(1,'#e5c28d');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);let sun=ctx.createRadialGradient(W*.77,H*.13,4,W*.77,H*.13,90);sun.addColorStop(0,'#fff0bb');sun.addColorStop(1,'#f1d39200');ctx.fillStyle=sun;ctx.fillRect(W*.6,0,W*.35,horizon);ctx.fillStyle='#84946c';ctx.fillRect(0,horizon,W,H-horizon);ctx.fillStyle='#536b50';for(let i=0;i<42;i++){let x=rng(i+45)*W,y=horizon-10+rng(i+92)*70,h=25+rng(i+80)*70;ctx.fillStyle=['#536d50','#687b55','#425f4b'][i%3];ctx.beginPath();ctx.moveTo(x,y-h);ctx.lineTo(x-h*.32,y);ctx.lineTo(x+h*.32,y);ctx.fill();ctx.fillRect(x-2,y-2,4,10)}
// Perspective road and verge bands
let N=48;for(let i=N-1;i>=0;i--){let a=i/N,b=(i+1)/N;let ya=horizon+(H-horizon)*a*a,yb=horizon+(H-horizon)*b*b;let ca=roadCenter(game.distance/1000+a*900),cb=roadCenter(game.distance/1000+b*900);let wa=20+a*W*.47,wb=20+b*W*.47;let stripe=Math.floor((game.distance/90+i/3));let edge=stripe%2?'#dbd0aa':'#d8c98f';poly([[ca-wa-14*a,ya],[ca-wa,ya],[cb-wb,yb],[cb-wb-14*b,yb]],edge);poly([[ca+wa,ya],[ca+wa+14*a,ya],[cb+wb+14*b,yb],[cb+wb,yb]],edge);poly([[ca-wa,ya],[ca+wa,ya],[cb+wb,yb],[cb-wb,yb]],stripe%2?'#686859':'#706c5d');if(stripe%2===0){let mw=1+a*5;poly([[ca-mw,ya],[ca+mw,ya],[cb+mw*1.1,yb],[cb-mw*1.1,yb]],'#dfd6b7')}}
// Roadside trunks/trees at repeat intervals
for(let side of [-1,1])for(let i=0;i<15;i++){let z=((i*112-game.distance%112+112)%112);let t=z/1200;if(t<.03||t>1)continue;let y=horizon+(H-horizon)*t*t,x=roadCenter(game.distance/1000+t*900)+side*(25+t*W*.55);let sz=10+t*60;ctx.fillStyle='#394c39';ctx.fillRect(x-sz*.08,y-sz*.12,sz*.16,sz*.4);ctx.fillStyle=['#385b42','#44664a','#526d4e'][i%3];ctx.beginPath();ctx.arc(x,y-sz*.22,sz*.4,0,7);ctx.fill();ctx.beginPath();ctx.arc(x-sz*.19,y-sz*.07,sz*.26,0,7);ctx.fill();ctx.beginPath();ctx.arc(x+sz*.19,y-sz*.08,sz*.24,0,7);ctx.fill()}
// road signs
if(game.distance<750){let t=.6,y=horizon+(H-horizon)*t*t,x=roadCenter(game.distance/1000+t*900)+W*.44;ctx.fillStyle='#e7e0c1';ctx.fillRect(x,y-48,4,52);ctx.fillStyle='#34513c';ctx.fillRect(x-22,y-68,60,27);ctx.fillStyle='#f0e5c8';ctx.font=`${Math.max(7,10*t)}px DM Mono`;ctx.fillText('KYLÄ  1.8',x-17,y-51)}
// Obstacles approaching the player
for(const o of game.obstacles){let rem=o.at-game.distance;if(rem<0||rem>450)continue;let t=1-rem/450,y=horizon+(H-horizon)*t*t,c=roadCenter(game.distance/1000+t*900),rw=20+t*W*.47,x=c+o.lane*rw*.62;let s=5+t*42;ctx.fillStyle='#20251f77';ctx.beginPath();ctx.ellipse(x,y+3*s/5,s,s*.3,0,0,7);ctx.fill();if(o.type==='rock'){ctx.fillStyle='#736d5b';ctx.beginPath();ctx.moveTo(x-s,y);ctx.lineTo(x-s*.7,y-s*.65);ctx.lineTo(x+s*.2,y-s);ctx.lineTo(x+s,y-s*.35);ctx.lineTo(x+s*.8,y);ctx.fill()}else if(o.type==='log'){ctx.fillStyle='#9b673f';ctx.fillRect(x-s,y-s*.28,s*2,s*.55);ctx.fillStyle='#cf9a5c';ctx.fillRect(x-s*.7,y-s*.2,s*.18,s*.4)}else{ctx.fillStyle='#b9bc95';ctx.fillRect(x-s*.55,y-s*.8,s*1.1,s*.8);ctx.fillStyle='#79654b';ctx.fillRect(x-s*.38,y-s*.55,s*.76,s*.24)}}
// windshield framing and dashboard
ctx.fillStyle='#18221e';ctx.beginPath();ctx.moveTo(0,H);ctx.lineTo(0,H*.86);ctx.quadraticCurveTo(W*.5,H*.77,W,H*.86);ctx.lineTo(W,H);ctx.fill();let dash=ctx.createLinearGradient(0,H*.86,0,H);dash.addColorStop(0,'#38423a');dash.addColorStop(1,'#161d19');ctx.fillStyle=dash;ctx.fillRect(0,H*.91,W,H*.09);ctx.fillStyle='#b77545';ctx.fillRect(W*.08,H*.91,W*.84,8);drawCar(W*.5+game.lane*W*.19,H*.81,Math.min(W*.25,210),game.condition<65);
// vibration tint on collisions
if(game.collideFlash>0){ctx.fillStyle=`rgba(228,117,60,${game.collideFlash*.13})`;ctx.fillRect(0,0,W,H)}
}
function frame(t){let dt=Math.min(.04,(t-last)/1000||0);last=t;if(screen==='title')drawTitle();else if(screen==='garage')drawGarage();else if(screen==='drive'){if(!game.paused&&!game.done)update(dt);drawDrive(dt)}requestAnimationFrame(frame)}requestAnimationFrame(frame);
function update(dt){game.elapsed+=dt;let gas=keys.has('w')||keys.has('arrowup')||touch.gas,brake=keys.has(' ')||keys.has('s')||keys.has('arrowdown')||touch.brake;let steer=(keys.has('a')||keys.has('arrowleft')||touch.left?-1:0)+(keys.has('d')||keys.has('arrowright')||touch.right?1:0);game.steer+=(steer-game.steer)*Math.min(1,dt*5);game.lane=Math.max(-.96,Math.min(.96,game.lane+game.steer*dt*(.74+game.speed/120)));let target=gas?108:0;if(gas)game.speed+=dt*28;if(brake)game.speed-=dt*65;else if(!gas)game.speed-=dt*8;game.speed=Math.max(0,Math.min(145,game.speed));if(Math.abs(game.lane)>.79)game.speed=Math.max(0,game.speed-dt*18);game.distance+=game.speed/3.6*dt;game.collideFlash=Math.max(0,game.collideFlash-dt*3);if(game.distance>game.lastObstacle){let types=['rock','log','bucket'];game.obstacles.push({at:game.distance+250+rng(game.distance)*150,lane:[-.68,0,.68][Math.floor(rng(game.distance+4)*3)],type:types[Math.floor(rng(game.distance+9)*3)],hit:false});game.lastObstacle+=300}
for(const o of game.obstacles){if(!o.hit&&o.at-game.distance<10&&o.at-game.distance>-8&&Math.abs(game.lane-o.lane)<.34){o.hit=true;game.condition=Math.max(0,game.condition-18);game.speed*=.46;game.collideFlash=1;showToast('THUNK! Something just came loose. Take it easy.')}}game.obstacles=game.obstacles.filter(o=>o.at>game.distance-30);$('#speed').textContent=Math.round(game.speed);$('#distance').textContent=(game.distance/1000).toFixed(2);$('#conditionText').textContent=Math.round(game.condition);$('#conditionBar').style.width=game.condition+'%';$('#conditionBar').style.background=game.condition<35?'#e6753c':'#c8d78e';$('#tripBar').style.width=Math.min(100,game.distance/18)+'%';if(game.condition<=0)endGame(false);if(game.distance>=1800)endGame(true)}
const keys=new Set(),touch={left:false,right:false,gas:false,brake:false};addEventListener('keydown',e=>{let k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys.add(k);if(k==='escape'&&screen==='drive')togglePause()});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
$$('[data-drive]').forEach(b=>{let n=b.dataset.drive;const set=v=>{touch[n]=v};b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);set(true)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>set(false)))});
function showToast(msg){let el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}

const taskData=[{id:'battery',name:'Connect the battery',short:'Battery',tip:'The positive lead was left loose. Click the glowing spot to reconnect it.'},{id:'radiator',name:'Top up the radiator',short:'Coolant',tip:'A warm engine needs coolant. Give the radiator a quick fill.'},{id:'plugs',name:'Check the spark plugs',short:'Spark plugs',tip:'Four little sparks make this old engine come alive. Snug them up.'},{id:'wheel',name:'Tighten the wheel',short:'Front wheel',tip:'One wheel is looking wobbly. Give the lug nuts a final turn.'}];
let garage={done:{},count:0};
function buildGarage(){garage={done:{},count:0};$('#hotspots').innerHTML='';$('#taskList').innerHTML='';taskData.forEach((task,i)=>{let item=document.createElement('div');item.className='task'+(i===0?' active':'');item.id='task-'+task.id;item.innerHTML=`<span class="task-icon">${i+1}</span><span>${task.short}</span>`;$('#taskList').append(item);let b=document.createElement('button');b.className='hotspot';b.setAttribute('aria-label',task.name);let places={battery:[49,44],radiator:[58,44],plugs:[43,44],wheel:[29,50]}[task.id];b.style.left=places[0]+'%';b.style.top=places[1]+'%';b.addEventListener('click',()=>completeTask(task,b));$('#hotspots').append(b)});$('#garageProgress').style.width='0%';$('#driveBtn').classList.add('hidden');$('#taskTitle').textContent='Four things to check';$('#taskDesc').textContent="Your uncle's old Satsuma has been sitting all winter. Fix the marked parts before taking it out.";$('#toolNote').textContent='Click a glowing spot on the car to work on it.'}
function completeTask(task,button){if(garage.done[task.id])return;garage.done[task.id]=true;garage.count++;button.classList.add('done');button.classList.remove('');let item=$('#task-'+task.id);item.classList.remove('active');item.classList.add('done');item.querySelector('.task-icon').textContent='✓';let next=taskData.find(t=>!garage.done[t.id]);if(next){$('#task-'+next.id).classList.add('active');$('#taskTitle').textContent=next.name;$('#taskDesc').textContent=next.tip;$('#toolNote').textContent=['A firm click. That should hold.','Coolant glugs into the old radiator.','Good spark. She might actually start.','Lugs are tight. Ready for the road.'][garage.count-1]||'Nice work.'}$('#garageProgress').style.width=garage.count/4*100+'%';if(garage.count===4){$('#taskTitle').textContent='She’s ready to roll';$('#taskDesc').textContent='Not pretty, but she’ll get you there. Keep her on the road and watch for rocks.';$('#toolNote').textContent='WASD or arrow keys to steer and accelerate. Space to brake.';$('#driveBtn').classList.remove('hidden');showToast('Four jobs done. Let’s see if she starts.')}else showToast(task.name+' — sorted.')}
function showScreen(name){screen=name;$('#titleScreen').classList.toggle('hidden',name!=='title');$('#garageScreen').classList.toggle('hidden',name!=='garage');$('#hud').classList.toggle('hidden',name!=='drive');$('#driveControls').style.display=name==='drive'&&innerWidth<=720?'flex':'none'}
$('#startBtn').addEventListener('click',()=>{buildGarage();showScreen('garage')});
$('#driveBtn').addEventListener('click',()=>{game.distance=0;game.speed=0;game.condition=100;game.lane=0;game.steer=0;game.obstacles=[];game.lastObstacle=130;game.elapsed=0;game.paused=false;game.done=false;$('#modalBg').classList.add('hidden');showScreen('drive');showToast('The engine catches. Head for the village!')});
function openModal(title,body,buttons){$('#modal').innerHTML=`<div class="eyebrow">Summer Wrench · Day 01</div><h2>${title}</h2><p>${body}</p><div class="modal-actions">${buttons.map(b=>`<button class="btn ${b.secondary?'secondary':''}" data-modal="${b.id}">${b.label}</button>`).join('')}</div>`;$('#modalBg').classList.remove('hidden');$$('[data-modal]').forEach(b=>b.onclick=()=>modalAction(b.dataset.modal))}
function modalAction(which){if(which==='resume'){game.paused=false;$('#modalBg').classList.add('hidden')}if(which==='garage'){game.paused=false;$('#modalBg').classList.add('hidden');buildGarage();showScreen('garage')}if(which==='retry'){game.done=false;$('#modalBg').classList.add('hidden');$('#driveBtn').click()}if(which==='home'){game.paused=false;$('#modalBg').classList.add('hidden');showScreen('title')}}
function togglePause(){if(game.done)return;game.paused=!game.paused;if(game.paused)openModal('Take a breather','The road will wait. Your trip is saved right where you left it.',[{id:'resume',label:'Back on the road'},{id:'garage',label:'Back to shed',secondary:true}]);else $('#modalBg').classList.add('hidden')}
$('#pauseBtn').addEventListener('click',togglePause);
function endGame(win){if(game.done)return;game.done=true;game.speed=0;openModal(win?'Village reached!':'Not quite roadworthy',''+(win?'You rolled into the village shop just as the rally cars arrived. The Satsuma made it!':'The Satsuma has had enough. Head back to the shed and give her another try.')+'<br><br><span style="font:11px DM Mono;color:#c8d78e">DISTANCE '+(game.distance/1000).toFixed(2)+' KM &nbsp; · &nbsp; CONDITION '+Math.round(game.condition)+'%</span>',[{id:'retry',label:'Drive again'},{id:'home',label:'Main menu',secondary:true}])}
$('#modalBg').addEventListener('click',e=>{if(e.target===$('#modalBg')&&game.paused)modalAction('resume')});
// Keep touch controls hidden on desktop and clear held keys when the tab loses focus.
addEventListener('resize',()=>{if(screen==='drive')$('#driveControls').style.display=innerWidth<=720?'flex':'none'});addEventListener('blur',()=>{keys.clear();Object.keys(touch).forEach(k=>touch[k]=false)});
</script></body></html>

