function drawTitle(){let g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#e69a5e');g.addColorStop(.55,'#e5b675');g.addColorStop(1,'#586b51');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);let hz=H*.49;ctx.fillStyle='#779072';ctx.fillRect(0,hz,W,H-hz);for(let i=0;i<20;i++){let x=i*W/15-30,h=60+rng(i)*95;ctx.fillStyle='#4b684d';ctx.fillRect(x,hz-h,W/22,h)}ctx.fillStyle='#d5cc9d';ctx.beginPath();ctx.arc(W*.76,H*.22,48,0,7);ctx.fill();poly([[W*.38,hz],[W*.62,hz],[W*.91,H],[W*.1,H]],'#796d54');poly([[W*.46,hz],[W*.54,hz],[W*.7,H],[W*.3,H]],'#a59878');for(let i=0;i<7;i++){let yy=hz+(H-hz)*(i/7);line(W*.5-(yy-hz)*.34,yy,W*.5+(yy-hz)*.34,yy,'#dfd2ad',Math.max(1,(yy-hz)*.014))}drawCar(W*.5,H*.77,Math.min(W*.25,210),false);for(let i=0;i<50;i++){let x=rng(i+30)*W,y=hz+rng(i+90)*(H-hz);ctx.fillStyle=i%2?'#c3c981':'#e5d7a1';ctx.fillRect(x,y,2,2)}}
function drawCar(x,y,w,damaged=false){ctx.save();ctx.translate(x,y);ctx.scale(w/180,w/180);ctx.fillStyle='#18221d77';ctx.beginPath();ctx.ellipse(0,18,102,39,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#252a24';ctx.fillRect(-88,-28,28,67);ctx.fillRect(60,-28,28,67);ctx.fillStyle=damaged?'#6d6c55':'#bc7444';ctx.beginPath();ctx.moveTo(-88,-42);ctx.quadraticCurveTo(-75,-61,-48,-62);ctx.lineTo(50,-62);ctx.quadraticCurveTo(80,-58,88,-35);ctx.lineTo(93,39);ctx.quadraticCurveTo(79,60,55,61);ctx.lineTo(-53,61);ctx.quadraticCurveTo(-84,56,-91,38);ctx.closePath();ctx.fill();ctx.strokeStyle='#29352b';ctx.lineWidth=5;ctx.stroke();ctx.fillStyle='#344940';ctx.beginPath();ctx.moveTo(-51,-53);ctx.lineTo(49,-53);ctx.lineTo(63,-18);ctx.lineTo(-61,-18);ctx.closePath();ctx.fill();ctx.fillRect(-66,20,131,28);ctx.fillStyle='#e2d7ac';ctx.fillRect(-85,-33,17,14);ctx.fillRect(68,-33,17,14);ctx.fillStyle='#322e27';ctx.fillRect(-74,-57,18,10);ctx.fillRect(55,-57,18,10);ctx.strokeStyle='#7d4d32';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-62,0);ctx.lineTo(64,0);ctx.stroke();if(damaged){ctx.fillStyle='#262c27';ctx.fillRect(-49,-7,98,19);ctx.strokeStyle='#929078';ctx.lineWidth=2;ctx.strokeRect(-49,-7,98,19)}ctx.restore()}
function drawGarage(){let sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#68796c');sky.addColorStop(.7,'#a69b76');sky.addColorStop(1,'#5c5544');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);let floor=H*.5;ctx.fillStyle='#d0b779';ctx.fillRect(0,floor,W,H-floor);for(let i=0;i<8;i++){let y=floor+i*i*3;line(0,y,W,y,'#8e805e66',1)}for(let x=0;x<W;x+=100)line(x,floor,x+(x-W/2)*.3,H,'#8e805e55',1);ctx.fillStyle='#323b30';ctx.fillRect(0,0,W,floor*.54);ctx.fillStyle='#64745e';ctx.fillRect(0,floor*.54,W,floor*.46);for(let x=0;x<W;x+=85){ctx.fillStyle=x%2?'#baa16b':'#c7ae79';ctx.fillRect(x,0,3,floor*.54)}ctx.fillStyle='#e0c58f';ctx.fillRect(W*.1,H*.05,W*.25,H*.34);ctx.fillStyle='#50665b';ctx.fillRect(W*.12,H*.075,W*.21,H*.3);line(W*.225,H*.075,W*.225,H*.375,'#d9c99e',4);line(W*.12,H*.22,W*.33,H*.22,'#d9c99e',4);ctx.fillStyle='#e7d5a5';ctx.fillRect(W*.7,H*.07,100,40);ctx.fillStyle='#71573d';ctx.font='bold 18px Oswald';ctx.fillText('TYÖKALUT',W*.7+12,H*.07+27);for(let i=0;i<5;i++){ctx.fillStyle=['#b84731','#51755c','#dfbf74','#746a51','#ae7950'][i];ctx.fillRect(W*.72+i*16,H*.2+(i%2)*18,9,47)}ctx.fillStyle='#495242';ctx.fillRect(W*.43,H*.1,W*.17,H*.19);ctx.fillStyle='#d2bd8c';ctx.fillRect(W*.435,H*.105,W*.16,H*.18);ctx.fillStyle='#596757';ctx.fillRect(W*.44,H*.11,W*.15,H*.16);drawCar(W*.5,H*.57,Math.min(W*.56,480),garage.done.battery&&garage.done.radiator&&garage.done.plugs&&garage.done.wheel);ctx.fillStyle='#2c352d';ctx.fillRect(W*.08,H*.61,70,95);ctx.fillStyle='#a56f48';ctx.fillRect(W*.095,H*.63,54,30);ctx.fillStyle='#e7d5a5';ctx.font='11px DM Mono';ctx.fillText('OIL',W*.12,H*.68);ctx.fillStyle='#30372d';ctx.fillRect(W*.81,H*.63,90,110);ctx.fillStyle='#cfb982';ctx.fillRect(W*.82,H*.65,70,10)}
const game={distance:0,speed:0,condition:100,lane:0,steer:0,obstacles:[],lastObstacle:180,elapsed:0,paused:false,done:false,collideFlash:0};function roadCenter(p){return W*.5+Math.sin(p*.0015)*W*.11+Math.sin(p*.00057+1.4)*W*.07}

function drawDrive(){let horizon=H*.37;let sky=ctx.createLinearGradient(0,0,0,horizon);sky.addColorStop(0,'#83b1b2');sky.addColorStop(1,'#e5c28d');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);let sun=ctx.createRadialGradient(W*.77,H*.13,4,W*.77,H*.13,90);sun.addColorStop(0,'#fff0bb');sun.addColorStop(1,'#f1d39200');ctx.fillStyle=sun;ctx.fillRect(W*.6,0,W*.35,horizon);ctx.fillStyle='#84946c';ctx.fillRect(0,horizon,W,H-horizon);for(let i=0;i<42;i++){let x=rng(i+45)*W,y=horizon-10+rng(i+92)*70,h=25+rng(i+80)*70;ctx.fillStyle=['#536d50','#687b55','#425f4b'][i%3];ctx.beginPath();ctx.moveTo(x,y-h);ctx.lineTo(x-h*.32,y);ctx.lineTo(x+h*.32,y);ctx.fill();ctx.fillRect(x-2,y-2,4,10)}let N=48;for(let i=N-1;i>=0;i--){let a=i/N,b=(i+1)/N,ya=horizon+(H-horizon)*a*a,yb=horizon+(H-horizon)*b*b,ca=roadCenter(game.distance/1000+a*900),cb=roadCenter(game.distance/1000+b*900),wa=20+a*W*.47,wb=20+b*W*.47,stripe=Math.floor(game.distance/90+i/3),edge=stripe%2?'#dbd0aa':'#d8c98f';poly([[ca-wa-14*a,ya],[ca-wa,ya],[cb-wb,yb],[cb-wb-14*b,yb]],edge);poly([[ca+wa,ya],[ca+wa+14*a,ya],[cb+wb+14*b,yb],[cb+wb,yb]],edge);poly([[ca-wa,ya],[ca+wa,ya],[cb+wb,yb],[cb-wb,yb]],stripe%2?'#686859':'#706c5d');if(stripe%2===0){let mw=1+a*5;poly([[ca-mw,ya],[ca+mw,ya],[cb+mw*1.1,yb],[cb-mw*1.1,yb]],'#dfd6b7')}}for(let side of [-1,1])for(let i=0;i<15;i++){let z=((i*112-game.distance%112+112)%112),t=z/1200;if(t<.03||t>1)continue;let y=horizon+(H-horizon)*t*t,x=roadCenter(game.distance/1000+t*900)+side*(25+t*W*.55),sz=10+t*60;ctx.fillStyle='#394c39';ctx.fillRect(x-sz*.08,y-sz*.12,sz*.16,sz*.4);ctx.fillStyle=['#385b42','#44664a','#526d4e'][i%3];ctx.beginPath();ctx.arc(x,y-sz*.22,sz*.4,0,7);ctx.fill();ctx.beginPath();ctx.arc(x-sz*.19,y-sz*.07,sz*.26,0,7);ctx.fill();ctx.beginPath();ctx.arc(x+sz*.19,y-sz*.08,sz*.24,0,7);ctx.fill()}if(game.distance<750){let t=.6,y=horizon+(H-horizon)*t*t,x=roadCenter(game.distance/1000+t*900)+W*.44;ctx.fillStyle='#e7e0c1';ctx.fillRect(x,y-48,4,52);ctx.fillStyle='#34513c';ctx.fillRect(x-22,y-68,60,27);ctx.fillStyle='#f0e5c8';ctx.font=`${Math.max(7,10*t)}px DM Mono`;ctx.fillText('KYLÄ  1.8',x-17,y-51)}for(const o of game.obstacles){let rem=o.at-game.distance;if(rem<0||rem>450)continue;let t=1-rem/450,y=horizon+(H-horizon)*t*t,c=roadCenter(game.distance/1000+t*900),rw=20+t*W*.47,x=c+o.lane*rw*.62,s=5+t*42;ctx.fillStyle='#20251f77';ctx.beginPath();ctx.ellipse(x,y+3*s/5,s,s*.3,0,0,7);ctx.fill();if(o.type==='rock'){ctx.fillStyle='#736d5b';ctx.beginPath();ctx.moveTo(x-s,y);ctx.lineTo(x-s*.7,y-s*.65);ctx.lineTo(x+s*.2,y-s);ctx.lineTo(x+s,y-s*.35);ctx.lineTo(x+s*.8,y);ctx.fill()}else if(o.type==='log'){ctx.fillStyle='#9b673f';ctx.fillRect(x-s,y-s*.28,s*2,s*.55);ctx.fillStyle='#cf9a5c';ctx.fillRect(x-s*.7,y-s*.2,s*.18,s*.4)}else{ctx.fillStyle='#b9bc95';ctx.fillRect(x-s*.55,y-s*.8,s*1.1,s*.8);ctx.fillStyle='#79654b';ctx.fillRect(x-s*.38,y-s*.55,s*.76,s*.24)}}ctx.fillStyle='#18221e';ctx.beginPath();ctx.moveTo(0,H);ctx.lineTo(0,H*.86);ctx.quadraticCurveTo(W*.5,H*.77,W,H*.86);ctx.lineTo(W,H);ctx.fill();let dash=ctx.createLinearGradient(0,H*.86,0,H);dash.addColorStop(0,'#38423a');dash.addColorStop(1,'#161d19');ctx.fillStyle=dash;ctx.fillRect(0,H*.91,W,H*.09);ctx.fillStyle='#b77545';ctx.fillRect(W*.08,H*.91,W*.84,8);drawCar(W*.5+game.lane*W*.19,H*.81,Math.min(W*.25,210),game.condition<65);if(game.collideFlash>0){ctx.fillStyle=`rgba(228,117,60,${game.collideFlash*.13})`;ctx.fillRect(0,0,W,H)}}
function frame(t){let dt=Math.min(.04,(t-last)/1000||0);last=t;if(screen==='title')drawTitle();else if(screen==='garage')drawGarage();else if(screen==='drive'){if(!game.paused&&!game.done)update(dt);drawDrive()}requestAnimationFrame(frame)}requestAnimationFrame(frame);
function update(dt){game.elapsed+=dt;let gas=keys.has('w')||keys.has('arrowup')||touch.gas,brake=keys.has(' ')||keys.has('s')||keys.has('arrowdown')||touch.brake;let steer=(keys.has('a')||keys.has('arrowleft')||touch.left?-1:0)+(keys.has('d')||keys.has('arrowright')||touch.right?1:0);game.steer+=(steer-game.steer)*Math.min(1,dt*5);game.lane=Math.max(-.96,Math.min(.96,game.lane+game.steer*dt*(.74+game.speed/120)));if(gas)game.speed+=dt*28;if(brake)game.speed-=dt*65;else if(!gas)game.speed-=dt*8;game.speed=Math.max(0,Math.min(145,game.speed));if(Math.abs(game.lane)>.79)game.speed=Math.max(0,game.speed-dt*18);game.distance+=game.speed/3.6*dt;game.collideFlash=Math.max(0,game.collideFlash-dt*3);if(game.distance>game.lastObstacle){let types=['rock','log','bucket'];game.obstacles.push({at:game.distance+250+rng(game.distance)*150,lane:[-.68,0,.68][Math.floor(rng(game.distance+4)*3)],type:types[Math.floor(rng(game.distance+9)*3)],hit:false});game.lastObstacle+=300}for(const o of game.obstacles){if(!o.hit&&o.at-game.distance<10&&o.at-game.distance>-8&&Math.abs(game.lane-o.lane)<.34){o.hit=true;game.condition=Math.max(0,game.condition-18);game.speed*=.46;game.collideFlash=1;showToast('THUNK! Something just came loose. Take it easy.')}}game.obstacles=game.obstacles.filter(o=>o.at>game.distance-30);$('#speed').textContent=Math.round(game.speed);$('#distance').textContent=(game.distance/1000).toFixed(2);$('#conditionText').textContent=Math.round(game.condition);$('#conditionBar').style.width=game.condition+'%';$('#conditionBar').style.background=game.condition<35?'#e6753c':'#c8d78e';$('#tripBar').style.width=Math.min(100,game.distance/18)+'%';if(game.condition<=0)endGame(false);if(game.distance>=1800)endGame(true)}

const keys=new Set(),touch={left:false,right:false,gas:false,brake:false};addEventListener('keydown',e=>{let k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys.add(k);if(k==='escape'&&screen==='drive')togglePause()});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));$$('[data-drive]').forEach(b=>{let n=b.dataset.drive;const set=v=>{touch[n]=v};b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);set(true)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>set(false)))});function showToast(msg){let el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
const taskData=[{id:'battery',name:'Connect the battery',short:'Battery',tip:'The positive lead was left loose. Click the glowing spot to reconnect it.'},{id:'radiator',name:'Top up the radiator',short:'Coolant',tip:'A warm engine needs coolant. Give the radiator a quick fill.'},{id:'plugs',name:'Check the spark plugs',short:'Spark plugs',tip:'Four little sparks make this old engine come alive. Snug them up.'},{id:'wheel',name:'Tighten the wheel',short:'Front wheel',tip:'One wheel is looking wobbly. Give the lug nuts a final turn.'}];let garage={done:{},count:0};function buildGarage(){garage={done:{},count:0};$('#hotspots').innerHTML='';$('#taskList').innerHTML='';taskData.forEach((task,i)=>{let item=document.createElement('div');item.className='task'+(i===0?' active':'');item.id='task-'+task.id;item.innerHTML=`<span class="task-icon">${i+1}</span><span>${task.short}</span>`;$('#taskList').append(item);let b=document.createElement('button');b.className='hotspot';b.setAttribute('aria-label',task.name);let places={battery:[49,44],radiator:[58,44],plugs:[43,44],wheel:[29,50]}[task.id];b.style.left=places[0]+'%';b.style.top=places[1]+'%';b.addEventListener('click',()=>completeTask(task,b));$('#hotspots').append(b)});$('#garageProgress').style.width='0%';$('#driveBtn').classList.add('hidden');$('#taskTitle').textContent='Four things to check';$('#taskDesc').textContent="Your uncle's old Satsuma has been sitting all winter. Fix the marked parts before taking it out.";$('#toolNote').textContent='Click a glowing spot on the car to work on it.'}
function completeTask(task,button){if(garage.done[task.id])return;garage.done[task.id]=true;garage.count++;button.classList.add('done');let item=$('#task-'+task.id);item.classList.remove('active');item.classList.add('done');item.querySelector('.task-icon').textContent='✓';let next=taskData.find(t=>!garage.done[t.id]);if(next){$('#task-'+next.id).classList.add('active');$('#taskTitle').textContent=next.name;$('#taskDesc').textContent=next.tip;$('#toolNote').textContent=['A firm click. That should hold.','Coolant glugs into the old radiator.','Good spark. She might actually start.','Lugs are tight. Ready for the road.'][garage.count-1]||'Nice work.'}$('#garageProgress').style.width=garage.count/4*100+'%';if(garage.count===4){$('#taskTitle').textContent='She’s ready to roll';$('#taskDesc').textContent='Not pretty, but she’ll get you there. Keep her on the road and watch for rocks.';$('#toolNote').textContent='WASD or arrow keys to steer and accelerate. Space to brake.';$('#driveBtn').classList.remove('hidden');showToast('Four jobs done. Let’s see if she starts.')}else showToast(task.name+' — sorted.')}
function showScreen(name){screen=name;$('#titleScreen').classList.toggle('hidden',name!=='title');$('#garageScreen').classList.toggle('hidden',name!=='garage');$('#hud').classList.toggle('hidden',name!=='drive');$('#driveControls').style.display=name==='drive'&&innerWidth<=720?'flex':'none'}$('#startBtn').addEventListener('click',()=>{buildGarage();showScreen('garage')});$('#driveBtn').addEventListener('click',()=>{game.distance=0;game.speed=0;game.condition=100;game.lane=0;game.steer=0;game.obstacles=[];game.lastObstacle=130;game.elapsed=0;game.paused=false;game.done=false;$('#modalBg').classList.add('hidden');showScreen('drive');showToast('The engine catches. Head for the village!')});
function openModal(title,body,buttons){$('#modal').innerHTML=`<div class="eyebrow">Summer Wrench · Day 01</div><h2>${title}</h2><p>${body}</p><div class="modal-actions">${buttons.map(b=>`<button class="btn ${b.secondary?'secondary':''}" data-modal="${b.id}">${b.label}</button>`).join('')}</div>`;$('#modalBg').classList.remove('hidden');$$('[data-modal]').forEach(b=>b.onclick=()=>modalAction(b.dataset.modal))}function modalAction(which){if(which==='resume'){game.paused=false;$('#modalBg').classList.add('hidden')}if(which==='garage'){game.paused=false;$('#modalBg').classList.add('hidden');buildGarage();showScreen('garage')}if(which==='retry'){game.done=false;$('#modalBg').classList.add('hidden');$('#driveBtn').click()}if(which==='home'){game.paused=false;$('#modalBg').classList.add('hidden');showScreen('title')}}function togglePause(){if(game.done)return;game.paused=!game.paused;if(game.paused)openModal('Take a breather','The road will wait. Your trip is saved right where you left it.',[{id:'resume',label:'Back on the road'},{id:'garage',label:'Back to shed',secondary:true}]);else $('#modalBg').classList.add('hidden')}$('#pauseBtn').addEventListener('click',togglePause);function endGame(win){if(game.done)return;game.done=true;game.speed=0;openModal(win?'Village reached!':'Not quite roadworthy',(win?'You rolled into the village shop just as the rally cars arrived. The Satsuma made it!':'The Satsuma has had enough. Head back to the shed and give her another try.')+'<br><br><span style="font:11px DM Mono;color:#c8d78e">DISTANCE '+(game.distance/1000).toFixed(2)+' KM &nbsp; · &nbsp; CONDITION '+Math.round(game.condition)+'%</span>',[{id:'retry',label:'Drive again'},{id:'home',label:'Main menu',secondary:true}])}$('#modalBg').addEventListener('click',e=>{if(e.target===$('#modalBg')&&game.paused)modalAction('resume')});addEventListener('resize',()=>{if(screen==='drive')$('#driveControls').style.display=innerWidth<=720?'flex':'none'});addEventListener('blur',()=>{keys.clear();Object.keys(touch).forEach(k=>touch[k]=false)});
</script></main></body></html>

@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;600;700;800&family=Oswald:wght@500;600;700&display=swap');
:root{--ink:#17231c;--paper:#f0ead8;--orange:#e6753c;--lime:#c8d78e}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#18251e;color:var(--paper);font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit;cursor:pointer}#game{position:relative;width:100%;height:100%;overflow:hidden}canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.grain{position:absolute;inset:0;pointer-events:none;z-index:2;opacity:.1;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.32'/%3E%3C/svg%3E")}.screen{position:absolute;inset:0;z-index:3;display:flex;align-items:center;justify-content:center}.hidden{display:none!important}.eyebrow{font:500 11px 'DM Mono',monospace;letter-spacing:.18em;text-transform:uppercase;color:var(--lime)}.title{font:700 clamp(46px,8vw,112px)/.86 'Oswald',sans-serif;letter-spacing:-.04em;text-transform:uppercase;margin:16px 0}.title span{color:var(--orange)}.subtitle{color:#d2cfbf;line-height:1.55;max-width:390px;font-size:15px}.btn{border:0;background:var(--orange);color:#1e2119;padding:15px 22px;font:700 12px 'DM Mono',monospace;letter-spacing:.08em;text-transform:uppercase;display:inline-flex;align-items:center;gap:15px;transition:.18s}.btn:hover{transform:translateY(-2px);background:#f08d53}.btn.secondary{background:transparent;color:var(--paper);border:1px solid #ffffff50}.title-screen{justify-content:flex-start;padding:clamp(28px,8vw,120px);background:linear-gradient(90deg,#17231cf5 0%,#17231cce 38%,transparent 78%)}.hero-copy{max-width:600px}.hero-bottom{position:absolute;bottom:28px;left:clamp(28px,8vw,120px);right:clamp(28px,8vw,120px);display:flex;justify-content:space-between;font:10px 'DM Mono',monospace;letter-spacing:.12em;color:#d0ccb7a8;text-transform:uppercase}.hero-card{display:flex;gap:22px;margin-top:30px;align-items:center}.key-hint{font:11px 'DM Mono',monospace;line-height:1.8;color:#d0ccb7a8}.pill{border:1px solid #ffffff50;padding:3px 7px;margin:0 2px;color:var(--paper)}
.hud{position:absolute;z-index:4;inset:0;pointer-events:none;padding:22px 26px;display:flex;flex-direction:column;justify-content:space-between}.hud-top,.hud-bottom{display:flex;align-items:flex-start;justify-content:space-between;gap:16px}.brand{font:600 16px 'Oswald',sans-serif;letter-spacing:.12em;text-transform:uppercase}.brand small{display:block;color:#b9b8a9;font:10px 'DM Mono',monospace;letter-spacing:.12em;margin-top:3px}.hud-card{background:#18251edb;border:1px solid #ffffff24;padding:12px 15px;min-width:150px;backdrop-filter:blur(8px)}.hud-label{font:10px 'DM Mono',monospace;color:#c3c0ac;letter-spacing:.14em;text-transform:uppercase}.hud-value{font:600 21px 'Oswald',sans-serif;margin-top:3px}.hud-value small{font:10px 'DM Mono',monospace;color:#bdb9a8}.meter{height:4px;background:#ffffff30;margin-top:9px;width:150px}.meter i{height:100%;display:block;background:var(--lime);width:100%;transition:width .2s}.quest{background:#18251edb;border-left:3px solid var(--orange);padding:11px 15px;max-width:310px;backdrop-filter:blur(8px)}.quest strong{display:block;font:600 15px 'Oswald',sans-serif;text-transform:uppercase;letter-spacing:.04em;margin:4px 0}.quest small{font-size:11px;color:#c5c2b1}.speedbox{display:flex;align-items:end;gap:10px}.speednum{font:600 44px/.9 'Oswald',sans-serif}.speedunit{font:10px 'DM Mono',monospace;color:#c3c0ac;padding-bottom:3px}.hud-actions{pointer-events:auto;display:flex;gap:8px}.iconbtn{background:#18251edb;border:1px solid #ffffff40;padding:9px 12px;font:10px 'DM Mono',monospace;text-transform:uppercase;letter-spacing:.08em}.toast{position:absolute;z-index:5;left:50%;top:16%;transform:translate(-50%,-10px);opacity:0;transition:.3s;background:#18251eef;border:1px solid #ffffff30;padding:12px 19px;font:11px 'DM Mono',monospace;letter-spacing:.06em;text-align:center;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}
.panel{background:#17231cef;border:1px solid #ffffff25;box-shadow:0 18px 60px #0007;backdrop-filter:blur(14px)}.garage-layout{width:min(1120px,94vw);height:min(690px,90vh);display:grid;grid-template-columns:1fr 315px;gap:12px}.garage-scene{position:relative;overflow:hidden;background:#819078}.garage-scene:after{content:'';position:absolute;inset:0;pointer-events:none;background:linear-gradient(0deg,#17231c66,transparent 30%),linear-gradient(90deg,#17231c22,transparent 60%)}.garage-head{position:absolute;z-index:2;top:23px;left:24px}.garage-head h2{font:600 28px 'Oswald',sans-serif;text-transform:uppercase;margin:7px 0}.garage-car{position:absolute;z-index:2;width:70%;height:auto;left:15%;top:25%;filter:drop-shadow(0 16px 12px #17231c77)}#hotspots{position:absolute;inset:0;z-index:4;pointer-events:none}.hotspot{position:absolute;pointer-events:auto;width:40px;height:40px;border-radius:50%;border:2px solid #f4e9cd;background:#e6753c;color:#17231c;font-weight:800;box-shadow:0 0 0 7px #e6753c40;animation:pulse 1.5s infinite;cursor:pointer;transform:translate(-50%,-50%)}.hotspot.done{background:var(--lime);border-color:#f4e9cd;box-shadow:0 0 0 5px #c8d78e36;animation:none}@keyframes pulse{50%{box-shadow:0 0 0 12px #e6753c16}}.hotspot:after{content:'';position:absolute;inset:11px;border:2px solid #17231c;border-radius:50%}.garage-caption{position:absolute;z-index:3;bottom:19px;left:24px;font:10px 'DM Mono',monospace;color:#fff;letter-spacing:.12em;text-transform:uppercase}.garage-side{padding:24px;display:flex;flex-direction:column}.garage-side h3{font:600 24px 'Oswald',sans-serif;text-transform:uppercase;margin:8px 0 4px}.garage-side p{color:#c3c0ac;font-size:13px;line-height:1.5;margin:0 0 17px}.task-list{display:grid;gap:8px}.task{display:flex;align-items:center;gap:10px;border:1px solid #ffffff22;padding:10px;font-size:12px;color:#dbd8c8;transition:.2s}.task.active{border-color:var(--orange);background:#e6753c16}.task.done{color:#bfc991;border-color:#c8d78e55}.task-icon{width:24px;height:24px;border:1px solid #ffffff40;display:grid;place-items:center;font:12px 'DM Mono',monospace}.task.done .task-icon{background:var(--lime);color:#17231c;border:0}.tool-note{font:11px 'DM Mono',monospace;color:#b9b5a3;margin-top:auto;padding:14px 0}.garage-side .btn{justify-content:space-between;width:100%}.progress{height:3px;background:#ffffff22;margin:13px 0 17px}.progress i{display:block;background:var(--lime);height:100%;width:0;transition:.3s}
.modal-bg{position:absolute;inset:0;z-index:8;background:#101912c9;display:grid;place-items:center;padding:20px}.modal{width:min(440px,100%);padding:28px}.modal h2{font:600 30px 'Oswald',sans-serif;text-transform:uppercase;margin:8px 0}.modal p{color:#c3c0ac;font-size:13px;line-height:1.6}.modal-actions{display:flex;gap:10px;margin-top:20px}.modal-actions .btn{flex:1;justify-content:center}.drive-controls{display:none;pointer-events:auto;position:absolute;z-index:4;bottom:18px;left:12px;right:12px;justify-content:space-between}.drive-controls button{width:60px;height:60px;border-radius:50%;border:1px solid #ffffff70;background:#18251ebd;font:22px 'DM Mono',monospace;touch-action:none}.drive-controls .pedal{width:74px;height:74px;background:#e6753cdd;color:#17231c;font:10px 'DM Mono',monospace;font-weight:bold}.drive-controls .pair{display:flex;gap:8px;align-items:end}
@media(max-width:720px){.title-screen{padding:26px;background:linear-gradient(90deg,#17231cf2,#17231cb8 80%,#17231c50)}.title{font-size:68px}.hero-bottom{left:26px;right:26px;bottom:18px}.hero-bottom span:last-child{display:none}.garage-layout{height:94vh;width:96vw;grid-template-columns:1fr;grid-template-rows:minmax(0,1fr) auto;gap:0}.garage-scene{min-height:0}.garage-side{padding:15px 18px}.garage-side h3{font-size:20px}.garage-side p{font-size:11px;margin-bottom:8px}.garage-side .task-list{grid-template-columns:1fr 1fr;gap:5px}.task{padding:7px;font-size:10px}.task-icon{width:20px;height:20px}.tool-note{display:none}.garage-side .btn{padding:11px 15px}.progress{margin:8px 0 10px}.garage-car{width:90%;left:5%;top:28%}.garage-head{top:12px;left:15px}.garage-head h2{font-size:21px}.hud{padding:13px}.hud-card{min-width:116px;padding:8px 10px}.meter{width:110px}.quest{max-width:200px;padding:8px 10px}.quest strong{font-size:12px}.quest small{font-size:9px}.speednum{font-size:34px}.brand{font-size:13px}.hud-top{gap:7px}.hud-bottom{align-items:end}.iconbtn{padding:8px}.hud-bottom .quest{margin-bottom:6px}.hud-actions{gap:4px}.hud-bottom .hud-card{display:none}}
@media(max-height:650px) and (min-width:721px){.garage-layout{height:94vh}.garage-side{padding:16px}.task-list{gap:5px}.task{padding:7px}.garage-side p{margin-bottom:8px}.tool-note{padding:7px 0}}

