const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--disable-dev-shm-usage'] });
  const errors = [];
  const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
  mobile.on('pageerror', error => errors.push(error.message));
  await mobile.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  await mobile.locator('#startBtn').click();
  const garageBox = await mobile.locator('.garage-layout').boundingBox();
  if (!garageBox || garageBox.width > 390 || garageBox.height > 844) throw new Error('Garage layout overflows mobile viewport');
  for (const hotspot of await mobile.locator('.hotspot').all()) await hotspot.click();
  await mobile.locator('#driveBtn').click();
  if (await mobile.locator('#driveControls').evaluate(el => getComputedStyle(el).display) !== 'flex') throw new Error('Mobile driving controls are hidden');
  await mobile.locator('[data-drive="gas"]').dispatchEvent('pointerdown', { pointerId: 1, pointerType: 'touch', isPrimary: true });
  await mobile.waitForTimeout(600);
  await mobile.locator('[data-drive="gas"]').dispatchEvent('pointerup', { pointerId: 1, pointerType: 'touch', isPrimary: true });
  if (Number(await mobile.locator('#speed').textContent()) < 5) throw new Error('Touch gas control failed');
  const desktop = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 });
  desktop.on('pageerror', error => errors.push(error.message));
  await desktop.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  await desktop.locator('#startBtn').click();
  for (const hotspot of await desktop.locator('.hotspot').all()) await hotspot.click();
  await desktop.locator('#driveBtn').click();
  await desktop.keyboard.down('ArrowUp');
  await desktop.waitForTimeout(1400);
  await desktop.keyboard.up('ArrowUp');
  if (Number(await desktop.locator('#speed').textContent()) < 10) throw new Error('Keyboard gas control failed');
  await desktop.locator('#pauseBtn').click();
  await desktop.locator('[data-action="resume"]').click();
  await desktop.screenshot({ path: 'screenshots/summer-wrench-check.jpg', type: 'jpeg', quality: 78 });
  if (errors.length) throw new Error(`Browser errors: ${errors.join('; ')}`);
  console.log(JSON.stringify({ mobileGarage: garageBox, touchControls: 'passed', desktopKeyboard: 'passed', pauseResume: 'passed', browserErrors: errors.length }));
  await browser.close();
})().catch(error => { console.error(error); process.exit(1); });
